    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self.rule {
            LoopRule::IdenticalFailures => write!(
                f,
                "Aborting after {} identical failed calls to '{}' with arguments {} ({}). \
