fn verdict(&self, signature: &str) -> Option<LoopVerdict> {
    let (tool, arguments) = signature.split_once(':').unwrap_or((signature, ""));
    let verdict = |rule, count: u8, capped: bool| LoopVerdict {
        rule,
        tool: tool.to_string(),
        arguments: brief_arguments(arguments),
        count,
        call: self.calls,
        capped,
        last_error: None,
    };

    if self.consecutive_failures >= MAX_IDENTICAL_TOOL_FAILURES {
        return Some(verdict(LoopRule::IdenticalFailures, self.consecutive_failures, false));
    }
    if self.consecutive_identical_answers >= MAX_IDENTICAL_ANSWERS {
        return Some(verdict(LoopRule::IdenticalAnswers, self.consecutive_identical_answers, self.answer_capped));
    }
    if self.consecutive_cycle_steps >= MAX_CYCLE_STEPS {
        return Some(verdict(LoopRule::Cycle, self.consecutive_cycle_steps + 1, false));
    }
    if self.consecutive_empty_results >= MAX_EMPTY_RESULTS {
        return Some(verdict(LoopRule::EmptyResults, self.consecutive_empty_results, false));
    }
    None
}
