```rust
/// How much of a call's arguments a verdict shows.
///
/// The identifying part of an argument set is at its front -- a path, a query, a
/// command -- while a write carries a whole file behind it. A verdict is read in a
/// terminal and parsed by nobody, so a bounded prefix plus the real size is more
/// useful than either a truncated JSON blob or a page of file contents.
const MAX_ARGUMENTS_CHARS: usize = 200;

fn brief_arguments(arguments: &str) -> String {
    let total = arguments.chars().count();
    if total <= MAX_ARGUMENTS_CHARS {
        return arguments.to_string();
    }
    let prefix: String = arguments.chars().take(MAX_ARGUMENTS_CHARS).collect();
    format!("{prefix}… ({total} characters in all)")
}
